/// An sRGB colour: `rgb` is 0xRRGGBB, `alpha` 0–1.
public struct RGBA: Hashable, Sendable {
    public let rgb: UInt32
    public let alpha: Double
    public init(_ rgb: UInt32, alpha: Double = 1) {
        self.rgb = rgb
        self.alpha = alpha
    }
    public var red: Double { Double((rgb >> 16) & 0xFF) / 255 }
    public var green: Double { Double((rgb >> 8) & 0xFF) / 255 }
    public var blue: Double { Double(rgb & 0xFF) / 255 }
}

/// A colour token: its value in light and in dark appearance.
public struct ThemedColor: Hashable, Sendable {
    public let light: RGBA
    public let dark: RGBA
    public init(light: RGBA, dark: RGBA) {
        self.light = light
        self.dark = dark
    }
}

/// A gradient stop: its colour and its 0–1 location along the gradient.
