#if canImport(UIKit)
extension RGBA {
    public var uiColor: UIColor { UIColor(red: red, green: green, blue: blue, alpha: alpha) }
}

extension ThemedColor {
    /// A UIColor that follows the light or dark appearance.
    public var uiColor: UIColor {
        #if os(watchOS)
        // A watch is always dark, and UIKit there has no dynamic colours.
        dark.uiColor
        #else
        let light = light.uiColor, dark = dark.uiColor
        return UIColor { $0.userInterfaceStyle == .dark ? dark : light }
        #endif
    }
}
#elseif canImport(AppKit)
extension RGBA {
    public var nsColor: NSColor { NSColor(srgbRed: red, green: green, blue: blue, alpha: alpha) }
}

extension ThemedColor {
    /// An NSColor that follows the light or dark appearance.
    public var nsColor: NSColor {
        let light = light.nsColor, dark = dark.nsColor
        return NSColor(name: nil) { $0.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? dark : light }
    }
}
#endif

#if canImport(SwiftUI)
extension RGBA {
    public var color: Color { Color(.sRGB, red: red, green: green, blue: blue, opacity: alpha) }
}

extension ThemedColor {
    /// A Color that follows the light or dark appearance.
    public var color: Color {
        #if canImport(UIKit)
        Color(uiColor: uiColor)
        #else
        Color(nsColor: nsColor)
        #endif
    }
}

extension CubicBezier {
    public func animation(duration: TimeInterval) -> Animation {
        .timingCurve(x1, y1, x2, y2, duration: duration)
    }
}
